import{_ as e,H as _,f as a,i as r}from"./chunks/framework.BH2BK_3i.js";const f=JSON.parse('{"title":"续写新篇 | 塑造新时代的安全蓝图","description":"","frontmatter":{},"headers":[],"relativePath":"安全攻防技能30讲/续写新篇-塑造新时代的安全蓝图.md","filePath":"安全攻防技能30讲/续写新篇-塑造新时代的安全蓝图.md","lastUpdated":1779819738000}'),p={name:"安全攻防技能30讲/续写新篇-塑造新时代的安全蓝图.md"};function i(o,t,l,s,n,c){return _(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="续写新篇-塑造新时代的安全蓝图" tabindex="-1">续写新篇 | 塑造新时代的安全蓝图 <a class="header-anchor" href="#续写新篇-塑造新时代的安全蓝图" aria-label="Permalink to &quot;续写新篇 | 塑造新时代的安全蓝图&quot;">​</a></h1><p>你好，我是何为舟。</p><p>时隔5年，很高兴能借助这次迭代计划，继续与你一起聊安全。</p><p>这些年来，我持续在安全领域深耕，也陆续切换了几个不同的安全领域。不得不说，安全的scope确实过于庞大了，从传统的基础安全、到业务风控、内容安全、合规等等，每一个领域都有着各自的玩法，想要融会贯通确实需要相当长的经验积累。与此同时，新技术也在持续更新，比如LLM爆发就引发了一股新的安全热潮，也督促着我不断去学习新的技术和趋势。</p><p>同时，我也观察到， <strong>安全最近几年越来越“务实”了</strong>。刚开始撰写专栏的时候，安全行业还是一片欣欣向荣，安全大会层出不穷，各种安全产品营收创新高。但差不多2019-2020年起，国家开始组织大规模的攻防演练，各种法规不断落地，安全行业开始越来越讲究实战效果。很多以前看起来美好的安全产品和概念，一旦在实战中经不起挑战，很容易遭受挑战，惨遭淘汰。近两年，各乙方安全厂商的裁员潮和惨不忍睹的营收财报，一定程度上也代表着过去安全泡沫的破裂。</p><p>尽管普遍认为安全处于“寒冬”期，但我仍然相信安全存在的必要性。真金不怕火炼，泡沫的破裂同时也代表着新时代的到来，而只有经历过这一轮筛选，安全才能真正体现其价值。</p><p>因此，在这次加餐中， <strong>我想从更宏观的角度去描述安全建设的思路，并尝试以AI为例，阐述一下该如何去看待新的技术</strong>。希望通过这些话题的讨论，能够帮助你在这个动荡时代，建立自己的安全价值观，获得长期的个人发展。</p><p>目前拟定增加的话题如下：</p><ul><li>安全建设从0到1</li><li>安全建设从1到10</li><li>大模型时代的AI for Security</li><li>大模型时代的Security For AI</li><li>安全发展趋势</li></ul><p>如果你有更多想要了解的内容，欢迎在留言区告诉我！</p>',10)])])}const u=e(p,[["render",i]]);export{f as __pageData,u as default};
